import { test, expect, Page } from '@playwright/test';

test.describe('Long-running task persistence across page refreshes', () => {
  let page: Page;
  const TEST_URL = 'http://localhost:3000';

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto(TEST_URL);
  });

  test.afterEach(async () => {
    await page.close();
  });

  test('should persist task progress after page refresh', async () => {
    // Start a long-running task
    const startButton = page.getByRole('button', { name: /start task/i });
    await startButton.click();

    // Wait for task to start and show progress
    const progressIndicator = page.getByRole('progressbar');
    await expect(progressIndicator).toBeVisible();

    // Get initial progress value
    const initialProgress = await progressIndicator.getAttribute('aria-valuenow');
    expect(initialProgress).toBeDefined();

    // Wait a bit for task to make some progress
    await page.waitForTimeout(2000);

    // Get progress after some time
    const progressBeforeRefresh = await progressIndicator.getAttribute('aria-valuenow');
    const progressValueBeforeRefresh = parseInt(progressBeforeRefresh || '0');

    // Refresh the page
    await page.reload();

    // Wait for page to load and task to resume
    await page.waitForLoadState('networkidle');

    // Verify task is still running
    const resumedProgressIndicator = page.getByRole('progressbar');
    await expect(resumedProgressIndicator).toBeVisible();

    // Get progress after refresh
    const progressAfterRefresh = await resumedProgressIndicator.getAttribute('aria-valuenow');
    const progressValueAfterRefresh = parseInt(progressAfterRefresh || '0');

    // Progress should be maintained or increased (not reset to 0)
    expect(progressValueAfterRefresh).toBeGreaterThanOrEqual(progressValueBeforeRefresh);

    // Verify task status is still displayed
    const taskStatus = page.getByText(/task in progress/i);
    await expect(taskStatus).toBeVisible();
  });

  test('should complete task and persist completion status after refresh', async () => {
    // Start a long-running task
    const startButton = page.getByRole('button', { name: /start task/i });
    await startButton.click();

    // Wait for task to complete
    const completionMessage = page.getByText(/task completed/i);
    await expect(completionMessage).toBeVisible({ timeout: 30000 });

    // Get completion details
    const resultText = page.getByRole('region', { name: /task result/i });
    const resultContent = await resultText.textContent();

    // Refresh the page
    await page.reload();
    await page.waitForLoadState('networkidle');

    // Verify completion status persists
    const persistedCompletion = page.getByText(/task completed/i);
    await expect(persistedCompletion).toBeVisible();

    // Verify result data is still available
    const persistedResult = page.getByRole('region', { name: /task result/i });
    const persistedContent = await persistedResult.textContent();
    expect(persistedContent).toBe(resultContent);
  });

  test('should handle task cancellation and persist cancelled state', async () => {
    // Start a long-running task
    const startButton = page.getByRole('button', { name: /start task/i });
    await startButton.click();

    // Wait for task to start
    const progressIndicator = page.getByRole('progressbar');
    await expect(progressIndicator).toBeVisible();

    // Wait a bit for task to make progress
    await page.waitForTimeout(1000);

    // Cancel the task
    const cancelButton = page.getByRole('button', { name: /cancel task/i });
    await expect(cancelButton).toBeVisible();
    await cancelButton.click();

    // Wait for cancellation to be processed
    await page.waitForTimeout(500);

    // Verify task is cancelled
    const cancelledStatus = page.getByText(/task cancelled/i);
    await expect(cancelledStatus).toBeVisible();

    // Refresh the page
    await page.reload();
    await page.waitForLoadState('networkidle');

    // Verify cancelled state persists
    const persistedCancelledStatus = page.getByText(/task cancelled/i);
    await expect(persistedCancelledStatus).toBeVisible();

    // Verify start button is available again
    const newStartButton = page.getByRole('button', { name: /start task/i });
    await expect(newStartButton).toBeVisible();
  });

  test('should maintain task history across multiple refreshes', async () => {
    // Start first task
    let startButton = page.getByRole('button', { name: /start task/i });
    await startButton.click();

    // Wait for completion
    let completionMessage = page.getByText(/task completed/i);
    await expect(completionMessage).toBeVisible({ timeout: 30000 });

    // Refresh page
    await page.reload();
    await page.waitForLoadState('networkidle');

    // Verify first task is in history
    let taskHistory = page.getByRole('list', { name: /task history/i });
    let historyItems = taskHistory.getByRole('listitem');
    let initialCount = await historyItems.count();
    expect(initialCount).toBeGreaterThan(0);

    // Start second task
    startButton = page.getByRole('button', { name: /start task/i });
    await startButton.click();

    // Wait for completion
    completionMessage = page.getByText(/task completed/i);
    await expect(completionMessage).toBeVisible({ timeout: 30000 });

    // Refresh page again
    await page.reload();
    await page.waitForLoadState('networkidle');

    // Verify both tasks are in history
    taskHistory = page.getByRole('list', { name: /task history/i });
    historyItems = taskHistory.getByRole('listitem');
    const finalCount = await historyItems.count();
    expect(finalCount).toBe(initialCount + 1);
  });

  test('should restore task state from localStorage after browser restart simulation', async () => {
    // Start a long-running task
    const startButton = page.getByRole('button', { name: /start task/i });
    await startButton.click();

    // Wait for task to start
    const progressIndicator = page.getByRole('progressbar');
    await expect(progressIndicator).toBeVisible();

    // Wait for some progress
    await page.waitForTimeout(1500);

    // Get task ID from localStorage
    const taskId = await page.evaluate(() => {
      return localStorage.getItem('currentTaskId');
    });
    expect(taskId).toBeTruthy();

    // Close and reopen page (simulating browser restart)
    await page.close();
    page = await page.context()!.newPage();
    await page.goto(TEST_URL);

    // Wait for page to load and restore state
    await page.waitForLoadState('networkidle');

    // Verify task is restored
    const restoredProgressIndicator = page.getByRole('progressbar');
    await expect(restoredProgressIndicator).toBeVisible();

    // Verify same task ID is being tracked
    const restoredTaskId = await page.evaluate(() => {
      return localStorage.getItem('currentTaskId');
    });
    expect(restoredTaskId).toBe(taskId);

    // Verify task continues to completion
    const completionMessage = page.getByText(/task completed/i);
    await expect(completionMessage).toBeVisible({ timeout: 30000 });
  });
});
